        MotorUp := TRUE;
        MotorDown := FALSE;

    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF NOT AtTop THEN
            MotorDown := TRUE;
        ELSE
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    3: // Moving-down
        IF CallUp AND DoorClosed AND NOT AtBottom THEN
            State := 1;
        ELSIF AtBottom OR NOT DoorClosed THEN
            State := 0;
        END_IF;
        MotorUp := FALSE;
        MotorDown := TRUE;

END_CASE;

