        MotorUp := FALSE;
        MotorDown := TRUE;
        IF Not CallDown OR NOT DoorClosed THEN
            State := 2;
        ELSIF AtBottom OR NOT CallUp OR NOT DoorClosed THEN
            State := 0;
        END_IF;
END_CASE;

