PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_STAR : TIME := T#3s;
END_VAR

CASE EStop OF
    FALSE:
        State := 0;
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
    TRUE:
        CASE State OF
            0, 1, 2:
                State := 0;
                MainK := FALSE;
                StarK := FALSE;
                DeltaK := FALSE;
        END_CASE;
END_CASE;

CASE State OF
    0:
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
    1:
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        IF EStop OR StopPB THEN
            State := 0;
        ELSIF Time >= PT_STAR THEN
            State := 2;
        END_IF;
    2:
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF EStop OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

