PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
    Flame   : BOOL;
END_VAR
VAR_OUTPUT
    Fan     : BOOL;
    Fuel    : BOOL;
    Ignition: BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN  : TIME := T#2s;
END_VAR

CASE State OF
    0: // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF EStop OR (StartPB AND NOT EStop) THEN
            State := 1;
        END_IF;

    1: // Purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF T#3s.TimedOut OR (NOT EStop) OR (StartPB AND NOT EStop) THEN
            State := 2;
        ELSIF StopPB THEN
            State := 0;
        END_IF;

    2: // Ignite
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF T#2s.TimedOut OR (NOT EStop) OR (StartPB AND NOT EStop) THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        ELSIF StopPB THEN
            State := 0;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF (NOT EStop) OR (NOT Flame) OR StopPB THEN
            State := 0;
        END_IF;

END_CASE;

