    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT;
    PrevDemand : BOOL;
END_VAR

IF NOT EStop THEN
    Lead := 0;
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSIF Demand AND NOT PrevDemand THEN
    Lead := 1 - Lead;
ELSIF Demand THEN
    CASE Lead OF
        0: Pump1 := TRUE; Pump2 := FALSE;
        1: Pump1 := FALSE; Pump2 := TRUE;
    END_CASE;
END_IF;

PrevDemand := Demand;

