    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR
VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // Idle
        IF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := 2;
        ELSIF OpenCmd AND NOT OpenLimit AND NOT Obstruction THEN
            State := 1;
        END_IF;

    1: // Opening
        IF OpenLimit OR Obstruction THEN
            State := 0;
        END_IF;

    2: // Closing
        IF CloseLimit OR Obstruction THEN
            State := 0;
        END_IF;
END_CASE;

CASE State OF
    1:
        MotorOpen := TRUE;
        MotorClose := FALSE;
    2:
        MotorOpen := FALSE;
        MotorClose := TRUE;
    OTHERWISE:
        MotorOpen := FALSE;
        MotorClose := FALSE;
END_CASE;

END_PROGRAM

