                IF StartPB AND NOT StopPB AND EStop THEN
                    State := 3;
                ELSIF StopPB OR NOT Estop THEN
                    State := 2;
                END_IF;
        END_CASE;
    TRUE:
        State := 0;
END_CASE;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
