PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE EStop OF
    FALSE:
        CASE State OF
            0:
                IF StartPB AND NOT EStop THEN
                    State := 1;
                END_IF;
            1:
                IF StartPB AND NOT EStop AND NOT StopPB THEN
                    State := IIF(PT_SEQ.T# <= T#2s, State + 1, State);
                ELSIF StopPB OR EStop THEN
                    State := 0;
                END_IF;
            2:
                IF StartPB AND NOT EStop AND NOT StopPB THEN
                    State := IIF(PT_SEQ.T# <= T#2s, State + 1, State);
                ELSIF StopPB OR EStop THEN
                    State := 0;
                END_IF;
            3:
                IF StartPB AND NOT EStop AND NOT StopPB THEN
                    State := IIF(PT_SEQ.T# <= T#2s, State + 1, State);
                ELSIF StopPB OR EStop THEN
                    State := 0;
                END_IF;
        END_CASE;
    TRUE:
        State := 0;
END_CASE;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

END_PROGRAM

