                IF StartPB AND NOT StopPB THEN
                    State := IFF(StopPB, 0, 3);
                ELSIF NOT StartPB AND StopPB THEN
                    State := 0;
                END_IF;
        END_CASE;
    TRUE:
        State := 0;
END_CASE;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
