    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE EStop OF
    FALSE: State := 0;
END_CASE;

IF StopPB OR (NOT EStop) THEN
    State := 0;
ELSIF StartPB AND (State <= 3) THEN
    CASE State OF
        0: State := 1;
        1: State := 2;
        2: State := 3;
    END_CASE;
END_IF;

CASE State OF
    0: C1 := FALSE; C2 := FALSE; C3 := FALSE;
    1: C1 := FALSE; C2 := FALSE; C3 := TRUE;
    2: C1 := FALSE; C2 := TRUE; C3 := TRUE;
    3: C1 := TRUE; C2 := TRUE; C3 := TRUE;
END_CASE;

END_PROGRAM

