PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE EStop OF
    FALSE:  // E-stop active
        State := 0;
    TRUE:   // E-stop inactive
        CASE State OF
            0:
                IF StartPB AND NOT StopPB THEN
                    State := 1;
                END_IF;
            1:
                IF StartPB AND NOT StopPB THEN
                    IF State < 3 THEN
                        State := State + 1;
                    END_IF;
                ELSIF StopPB OR (State > 0) THEN
                    State := State - 1;
                END_IF;
            2:
                IF StartPB AND NOT StopPB THEN
                    IF State < 3 THEN
                        State := State + 1;
                    END_IF;
                ELSIF StopPB OR (State > 0) THEN
                    State := State - 1;
                END_IF;
            3:
                IF StartPB AND NOT StopPB THEN
                    IF State < 3 THEN
                        State := State + 1;
                    END_IF;
                ELSIF StopPB OR (State > 0) THEN
                    State := State - 1;
                END_IF;
        END_CASE;
END_CASE;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Done : BOOL;
END_VAR
VAR
    Count : INT;
    PrevTrigger : BOOL;
END_VAR

IF Reset THEN
    Count := 0;
ELSIF NOT PrevTrigger AND Trigger THEN
    Count := Count + 1;
END_IF;

PrevTrigger := Trigger;
Done := Count >= 3;

IF Reset THEN
    Done := FALSE;
END_IF;

END_PROGRAM

